import importlib.util, sys, dis, types, inspect, json
from pathlib import Path

# Load target module/function
import control.statesp as statesp
func = statesp._convert_to_statespace
tracked = {"A", "B", "C", "D", "d", "drow", "maxd", "maxn", "method", "n", "newsys", "nrow", "sys", "use_prefix_suffix"}

# Collect code objects: function + nested comprehensions/generators
code_objects = set()

def collect_codes(co):
    code_objects.add(co)
    for c in co.co_consts:
        if isinstance(c, types.CodeType):
            collect_codes(c)

collect_codes(func.__code__)

# Build offset->instruction map per code object
inst_maps = {co: {ins.offset: ins for ins in dis.get_instructions(co)} for co in code_objects}

# Function def line for params
func_def_line = func.__code__.co_firstlineno

# Load test module by path
qa_path = Path('/testbed/qa_instances_eval/python-control/statesp_convert_to_statespace_def_use_intersection_suite/files/tests/qa/statesp_convert_to_statespace_def_use_intersection_suite_test.py')
spec = importlib.util.spec_from_file_location('qa_test_mod', qa_path)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
TestCls = mod.TestConvertToStateSpaceDefUseIntersectionQA

# We'll call each method directly
method_names = [f'test_case_{i:02d}' for i in range(1, 11)]

all_sets = []

for mname in method_names:
    current_def = {}
    pairs = set()

    def tracer(frame, event, arg):
        co = frame.f_code

        if event == 'call':
            if co in code_objects:
                frame.f_trace_opcodes = True
                # parameters are defined at function definition line
                if co is func.__code__:
                    for pname in ('sys', 'use_prefix_suffix', 'method'):
                        current_def[pname] = func_def_line
                return tracer
            return None

        if co not in code_objects:
            return tracer

        if event == 'opcode':
            ins = inst_maps[co].get(frame.f_lasti)
            if ins is None:
                return tracer
            var = ins.argval if isinstance(ins.argval, str) else None
            line = frame.f_lineno
            if var in tracked:
                if ins.opname.startswith('STORE_'):
                    current_def[var] = line
                elif ins.opname.startswith('LOAD_'):
                    if var in current_def:
                        pairs.add((var, current_def[var], line))
        return tracer

    sys.settrace(tracer)
    try:
        getattr(TestCls(), mname)()
    finally:
        sys.settrace(None)

    all_sets.append(pairs)
    print(mname, len(pairs))

intersection = set.intersection(*all_sets)
print('INTERSECTION_COUNT', len(intersection))
for item in sorted(intersection, key=lambda x: (x[0], x[1], x[2])):
    print(item)

